# Push NamEngine launch content to Notion Content Calendar
$DB_ID = "3c0c8498-b23f-817b-9b89-c79ece48db31"

function PatchPage($id, $json) {
    $r = ntn api "v1/pages/$id" -X PATCH --data $json 2>&1
    if ($LASTEXITCODE -eq 0) { Write-Host "PATCH OK: $id" } else { Write-Host "PATCH FAIL: $id | $r" }
}

function CreatePage($json) {
    $r = ntn api v1/pages -X POST --data $json 2>&1
    if ($LASTEXITCODE -eq 0) {
        Write-Host "CREATE OK: $(($r | ConvertFrom-Json).id)"
    } else { Write-Host "CREATE FAIL: $r" }
}

