CreatePage "{`"parent`":{`"database_id`":`"3c0c8498-b23f-817b-9b89-c79ece48db31`"},`"properties`":{`"Post Title`":{`"title`":[{`"text`":{`"content`":`"Post 0 - We're Live: NamEngine for Baby, Pet, and Business`"}}]},`"Date`":{`"date`":{`"start`":`"2026-09-08`"}},`"Vertical`":{`"multi_select`":[{`"id`":`"213b7ae7-c32b-4b58-b987-899271025070`"},{`"id`":`"408ca4bb-c297-445d-ad82-d3f41a0d886c`"},{`"id`":`"d3978a95-6882-423c-a7a7-a629e35dbddd`"}]},`"Platform`":{`"multi_select`":[{`"id`":`"4f1ff3f9-9a8e-405b-b288-a0d464433160`"},{`"id`":`"8926985a-70e4-4dcd-8308-ce236bf6b4a7`"}]},`"Status`":{`"status`":{`"id`":`"2213dbe6-64fa-4c89-aacb-c36e4390dcd8`"}},`"Objective`":{`"select`":{`"id`":`"39f33c37-bc3d-4398-ae4c-d62f9d39ebb0`"}},`"CTA`":{`"rich_text`":[{`"text`":{`"content`":`"Try your free first list at nam-engine.com.`"}}]},`"Notes`":{`"rich_text`":[{`"text`":{`"content`":`"Hook: Finding names isn't the problem. Finding YOUR name is.\n\nCaption: NamEngine is live today for three kinds of naming decisions: Baby names with depth and style, Pet names that feel personal, Business names that sound credible before you explain the idea.\n\nStart with a free first list. Unlock the full experience for $4.99.\n\nnam-engine.com\n\nReel VO: The problem is never that there aren't enough options. There are thousands. The problem is finding the one that feels like it already belonged to you.`"}}]}}}"

CreatePage "{`"parent`":{`"database_id`":`"3c0c8498-b23f-817b-9b89-c79ece48db31`"},`"properties`":{`"Post Title`":{`"title`":[{`"text`":{`"content`":`"Day 3 - If You Love Milo But Want Something Less Common`"}}]},`"Date`":{`"date`":{`"start`":`"2026-09-15`"}},`"Vertical`":{`"multi_select`":[{`"id`":`"408ca4bb-c297-445d-ad82-d3f41a0d886c`"}]},`"Platform`":{`"multi_select`":[{`"id`":`"4f1ff3f9-9a8e-405b-b288-a0d464433160`"},{`"id`":`"8926985a-70e4-4dcd-8308-ce236bf6b4a7`"}]},`"Status`":{`"status`":{`"id`":`"2213dbe6-64fa-4c89-aacb-c36e4390dcd8`"}},`"Objective`":{`"select`":{`"id`":`"e586dee5-ea63-4f65-b939-da1863b13914`"}},`"CTA`":{`"rich_text`":[{`"text`":{`"content`":`"Save this list, or try a free first pet name list at nam-engine.com.`"}}]},`"Notes`":{`"rich_text`":[{`"text`":{`"content`":`"Hook: If you love Milo but want something a little less expected.\n\nFive alternatives: Otis, Remy, Arlo, Nico, Hugo. Each keeps Milo warmth with more room to make it yours.\n\nReel VO: If you love the name Milo for a pet, you are not alone. It is friendly, bright, and easy to say, which is exactly why it is everywhere. Try Otis, Remy, Arlo, Nico, or Hugo instead.`"}}]}}}"

CreatePage "{`"parent`":{`"database_id`":`"3c0c8498-b23f-817b-9b89-c79ece48db31`"},`"properties`":{`"Post Title`":{`"title`":[{`"text`":{`"content`":`"Day 4 - The Business Name Gut Check`"}}]},`"Date`":{`"date`":{`"start`":`"2026-09-17`"}},`"Vertical`":{`"multi_select`":[{`"id`":`"d3978a95-6882-423c-a7a7-a629e35dbddd`"}]},`"Platform`":{`"multi_select`":[{`"id`":`"4f1ff3f9-9a8e-405b-b288-a0d464433160`"},{`"id`":`"8926985a-70e4-4dcd-8308-ce236bf6b4a7`"}]},`"Status`":{`"status`":{`"id`":`"2213dbe6-64fa-4c89-aacb-c36e4390dcd8`"}},`"Objective`":{`"select`":{`"id`":`"eab55774-a9a1-472a-8515-285cd288b7f0`"}},`"CTA`":{`"rich_text`":[{`"text`":{`"content`":`"Find your business name through NamEngine at nam-engine.com.`"}}]},`"Notes`":{`"rich_text`":[{`"text`":{`"content`":`"Hook: You know a great business name when you hear one. Here's what makes it stick.\n\n1. Easy to say - if people hesitate, they will avoid saying it.\n2. Easy to spell - a clever name no one can type is expensive.\n3. Carries meaning without explaining itself - the best names suggest a world.\n\nReel VO: You can usually feel when a business name works before you can explain why. It sounds clean, easy to repeat, with a little meaning built in.`"}}]}}}"

CreatePage "{`"parent`":{`"database_id`":`"3c0c8498-b23f-817b-9b89-c79ece48db31`"},`"properties`":{`"Post Title`":{`"title`":[{`"text`":{`"content`":`"Day 6 - Nobody's Talking About: Luna Alternatives`"}}]},`"Date`":{`"date`":{`"start`":`"2026-09-22`"}},`"Vertical`":{`"multi_select`":[{`"id`":`"408ca4bb-c297-445d-ad82-d3f41a0d886c`"}]},`"Platform`":{`"multi_select`":[{`"id`":`"4f1ff3f9-9a8e-405b-b288-a0d464433160`"},{`"id`":`"8926985a-70e4-4dcd-8308-ce236bf6b4a7`"}]},`"Status`":{`"status`":{`"id`":`"2213dbe6-64fa-4c89-aacb-c36e4390dcd8`"}},`"Objective`":{`"select`":{`"id`":`"e586dee5-ea63-4f65-b939-da1863b13914`"}},`"CTA`":{`"rich_text`":[{`"text`":{`"content`":`"Save the list, then try a free pet name list at nam-engine.com.`"}}]},`"Notes`":{`"rich_text`":[{`"text`":{`"content`":`"Hook: Luna is everywhere. These are the alternatives nobody mentions.\n\nFive alternatives that keep the mood: Wren, Vesper, Cleo, Sable, Isadora.\n\nReel VO: Luna is everywhere because it works. But if you want the Luna feeling without the Luna popularity, try Wren, Vesper, Cleo, Sable, or Isadora.`"}}]}}}"

CreatePage "{`"parent`":{`"database_id`":`"3c0c8498-b23f-817b-9b89-c79ece48db31`"},`"properties`":{`"Post Title`":{`"title`":[{`"text`":{`"content`":`"Day 9 - The Name That Almost Wasn't`"}}]},`"Date`":{`"date`":{`"start`":`"2026-09-29`"}},`"Vertical`":{`"multi_select`":[{`"id`":`"408ca4bb-c297-445d-ad82-d3f41a0d886c`"}]},`"Platform`":{`"multi_select`":[{`"id`":`"4f1ff3f9-9a8e-405b-b288-a0d464433160`"},{`"id`":`"8926985a-70e4-4dcd-8308-ce236bf6b4a7`"}]},`"Status`":{`"status`":{`"id`":`"2213dbe6-64fa-4c89-aacb-c36e4390dcd8`"}},`"Objective`":{`"select`":{`"id`":`"76b61fea-60f8-4d69-80db-0a0c3f7f32ec`"}},`"CTA`":{`"rich_text`":[{`"text`":{`"content`":`"Comment the almost-name and the name that stuck. Try NamEngine for your free first pet name list.`"}}]},`"Notes`":{`"rich_text`":[{`"text`":{`"content`":`"Hook: What name did you almost give your pet before the real one stuck?\n\nCaption: Maybe they were almost Olive before they became Goose, Jasper before they became Beans, Daisy before they became Mabel, Apollo before they became Sock.\n\nReel VO: Every pet has an almost-name. The name you had picked before their actual personality showed up and ruined your plan.`"}}]}}}"

CreatePage "{`"parent`":{`"database_id`":`"3c0c8498-b23f-817b-9b89-c79ece48db31`"},`"properties`":{`"Post Title`":{`"title`":[{`"text`":{`"content`":`"Day 10 - Name DNA: Stripe`"}}]},`"Date`":{`"date`":{`"start`":`"2026-10-01`"}},`"Vertical`":{`"multi_select`":[{`"id`":`"d3978a95-6882-423c-a7a7-a629e35dbddd`"}]},`"Platform`":{`"multi_select`":[{`"id`":`"4f1ff3f9-9a8e-405b-b288-a0d464433160`"},{`"id`":`"8926985a-70e4-4dcd-8308-ce236bf6b4a7`"}]},`"Status`":{`"status`":{`"id`":`"2213dbe6-64fa-4c89-aacb-c36e4390dcd8`"}},`"Objective`":{`"select`":{`"id`":`"eab55774-a9a1-472a-8515-285cd288b7f0`"}},`"CTA`":{`"rich_text`":[{`"text`":{`"content`":`"Try NamEngine for a free first business name list at nam-engine.com.`"}}]},`"Notes`":{`"rich_text`":[{`"text`":{`"content`":`"Hook: Name DNA: Why Stripe works as a business name.\n\nStripe does not try to explain payments in the obvious way. Sound: short, crisp, one syllable. Shape: linear and clean, a mark, a band. Signal: suggests speed, order, clarity. What it avoids: no forced tech spelling, no generic pay construction.\n\nReel VO: Stripe works because it does not over-explain itself. Short, crisp, visual. A good business name points in the right direction without trapping the company inside one feature.`"}}]}}}"

CreatePage "{`"parent`":{`"database_id`":`"3c0c8498-b23f-817b-9b89-c79ece48db31`"},`"properties`":{`"Post Title`":{`"title`":[{`"text`":{`"content`":`"Day 12 - Sunday Pet Name List: Not the Obvious Ones`"}}]},`"Date`":{`"date`":{`"start`":`"2026-10-06`"}},`"Vertical`":{`"multi_select`":[{`"id`":`"408ca4bb-c297-445d-ad82-d3f41a0d886c`"}]},`"Platform`":{`"multi_select`":[{`"id`":`"4f1ff3f9-9a8e-405b-b288-a0d464433160`"},{`"id`":`"8926985a-70e4-4dcd-8308-ce236bf6b4a7`"}]},`"Status`":{`"status`":{`"id`":`"2213dbe6-64fa-4c89-aacb-c36e4390dcd8`"}},`"Objective`":{`"select`":{`"id`":`"e586dee5-ea63-4f65-b939-da1863b13914`"}},`"CTA`":{`"rich_text`":[{`"text`":{`"content`":`"Save this Sunday list, or try your free first pet name list at nam-engine.com.`"}}]},`"Notes`":{`"rich_text`":[{`"text`":{`"content`":`"Hook: Pet names that feel considered, not generic.\n\n10 names: Mabel, Otis, Cleo, Bowie, Fig, Winnie, Sable, Hugo, Pippa, Rune.\n\nReel VO: Pet names that feel considered, not generic. The best pet names are easy to say, but still feel like they belong to one specific animal, not every dog park and every list on the internet.`"}}]}}}"

CreatePage "{`"parent`":{`"database_id`":`"3c0c8498-b23f-817b-9b89-c79ece48db31`"},`"properties`":{`"Post Title`":{`"title`":[{`"text`":{`"content`":`"Day 13 - Would You Name Your Brand This?`"}}]},`"Date`":{`"date`":{`"start`":`"2026-10-08`"}},`"Vertical`":{`"multi_select`":[{`"id`":`"d3978a95-6882-423c-a7a7-a629e35dbddd`"}]},`"Platform`":{`"multi_select`":[{`"id`":`"4f1ff3f9-9a8e-405b-b288-a0d464433160`"},{`"id`":`"8926985a-70e4-4dcd-8308-ce236bf6b4a7`"}]},`"Status`":{`"status`":{`"id`":`"2213dbe6-64fa-4c89-aacb-c36e4390dcd8`"}},`"Objective`":{`"select`":{`"id`":`"76b61fea-60f8-4d69-80db-0a0c3f7f32ec`"}},`"CTA`":{`"rich_text`":[{`"text`":{`"content`":`"Comment your vote: Meridian Coffee or The Daily Press. Build your own at nam-engine.com.`"}}]},`"Notes`":{`"rich_text`":[{`"text`":{`"content`":`"Hook: Meridian Coffee vs. The Daily Press - which one would you go to?\n\nSame category. Very different signals. Meridian Coffee: polished, calm, slightly elevated. The Daily Press: familiar, active, community-based. One says refined pause. The other says everyday ritual.\n\nReel VO: Same category, totally different feeling. You are not just choosing words. You are choosing the promise people feel before they ever walk in.`"}}]}}}"

